        .IsStartingScreenFocused(true);                                                                                                                                                                                          
                                                                                                                                                                                                                                 
    Game.Create(configuration);                                                                                                                                                                                                  
    Game.Instance.Run();                                                                                                                                                                                                         
    Game.Instance.Dispose();                                                                                                                                                                                                     
                                                                                                                                                                                                                                 
    void Startup(object? sender, GameHost host)                                                                                                                                                                                  
    {                                                                                                                                                                                                                            
        // Tutaj przypiszemy nasz ekran główny do Game.Instance.Screen                                                                                                                                                           
    }                               